eef=np.array(m['proprio']['now'][26:29]); cp=(T[:3,:3].T@(eef-T[:3,3]))*[1,-1,-1];uv=K@cp;uv=uv[:2]/uv[2];print('eef',eef,'pixel',uv)
a=Image.open(p+'/'+c+'.png').resize((960,720));d=ImageDraw.Draw(a)
for u in range(0,320,20):
 d.line((u*3,0,u*3,720),fill='#888888');d.text((u*3,0),str(u),fill='yellow')
for v in range(0,240,20):
 d.line((0,v*3,960,v*3),fill='#888888');d.text((0,v*3),str(v),fill='yellow')
a.save('/app/runs/grid.png')
PY
